/** ENVIA_MOVIMIENTOS: hasta 5 ocurrencias de importe por movimiento, se detiene en la clave 0. */
List<Mensaje942> mensajes(MovimientoCb2 mov, boolean reenvio, int desdeOcurrencia) {
    if (mov.tipoProceso() >= 20 || mov.funcion() != 1) return List.of();
    List<Mensaje942> salida = new ArrayList<>();
    for (int i = reenvio ? desdeOcurrencia : 1; i <= 5 && mov.clave(i) > 0; i++) {
        ClaveBnx clave = claves.de(mov.clave(i));
        if (clave.indCiti() != 1 && clave.indCiti() != 2) continue;
        if (!claves.valida(clave)) continue;                         // VALIDA_CVE
        boolean cargo = clave.afectacionContable() == 1
                || props.clavesCargoForzado().contains(clave.numero());
        Importe imp = props.esImporteEditado(clave.numero())
                ? Importe.soloLeyenda(mov.importe(i))                // va en :86:, el :61: lleva cero
                : Importe.de(mov.entero(i), mov.decimal(i));
        builder.detalle(mov, clave, cargo, imp, i).ifPresent(salida::add);
        if (reenvio) break;                                          // INDICE := 6
    }
    return salida;
}

/** CUENTAS_CITY: sucursal 4 dígitos + cuenta 7 dígitos reordenados al formato interno Citi. */
public record CuentaCiti(String numeroBase, String formatoInterno) {
    public static CuentaCiti de(int sucursal, long cuenta) {
        String c = "%04d%07d".formatted(sucursal, cuenta);          // ARR_CTA, 11 dígitos
        String base = c.substring(2, 8);                             // DOUBLE(ARR_CTA[2],6)
        String interno = c.charAt(0) + c.substring(2, 8) + c.charAt(1) + c.substring(8, 11);
        return new CuentaCiti(base, interno);
    }
}

/** GRABA_ID_942: tags de identificación. El layout no es SWIFT estándar; se arma a mano. */
StringBuilder encabezado(MovimientoCb2 mov, CuentaCiti cta, long numeroMensaje) {
    String csi = props.csiLocal() == 4 ? "M" : "V";                  // Monterrey o Valle de México
    return new StringBuilder()
        .append("942 02").append(CRLF)
        .append(":20:484").append(csi).append("%06d".formatted(numeroMensaje)).append(CRLF)
        .append(":25:484-").append("%010d".formatted(Long.parseLong(cta.formatoInterno()) % 10_000_000_000L)).append(CRLF)
        .append(mov.moneda() == 1 ? ":34F:MXN0," : ":34F:USD0,").append(CRLF)
        .append(":13:").append(mov.fechaOperacionAammdd()).append(mov.horaOperacionHhmmss()).append(CRLF);
}

