/** GRABA_DET_942: estatus 1 = alta (D/C), otro = eliminación (RD/RC). */
Optional<Mensaje942> detalle(MovimientoCb2 mov, ClaveBnx clave, boolean cargo, Importe imp, int occ) {
    boolean alta = mov.status() == 1;
    int claveCiti = alta ? clave.citi() : clave.citiReverso();
    LocalDate fechaValor = mov.fechaValor().orElse(mov.fechaContable());
    boolean gpp = clave.numero() == 2229 && (mov.sistemaOrigen() == 15 || mov.sistemaOrigen() == 999);

    if (cargo && !gpp && props.cargosExcluidos().aplica(mov.cajaInicial(), mov.sucursalInicial())) {
        return Optional.empty();                                    // no se envía ni se registra
    }
    String marca = (alta ? "" : "R") + (cargo ? "D" : "C");
    String referencia = gpp ? mov.referenciaCliente().map(r -> "%-16s".formatted(r)).orElse("NONREF          ")
                            : mov.referenciaMovimiento().map("%016d"::formatted).orElse("NONREF");
    String tag61 = ":61:" + AAMMDD.format(fechaValor) + mov.mmddContable() + marca
            + "%03d".formatted(claveCiti) + "%012d".formatted(imp.entero()) + "," + "%02d".formatted(imp.decimales())
            + "NMSC" + referencia + "//" + "%04d".formatted(mov.sucursalInicial())
            + "%06d".formatted(mov.autorizacion()) + CRLF;
    return Optional.of(new Mensaje942(encabezado(mov, cuenta(mov), estado.siguienteMensaje()), tag61,
                                      adicionales(mov, clave, occ)));   // GRABA_ADI_942: tag :86:
}

