// ---------------------------------------------------------------------------
@Transactional
void envia(Mensaje942 m, MovimientoCb2 mov, int ocurrencia) {
    byte[] msg = HeaderInfraestructura.de(props.header(), estado.csiDestino(), props.csiLocal(),
                                          m.numero(), estado.esReenvio())
                                      .concatena(m.cuerpo()).ebcdic();
    int rc = tcp.enviaAOtroCsi(msg);
    if (rc != 0) {
        log.warn("RESULT TCP CARRIER {}", rc);
        if (rc == 10 || rc == 33) {
            estado.desligaTcp();                                   // DESLIGA_TCP: corta el bloque
            notificador.carrierDesligado(rc);                      // COMMANDPOST, una vez por incidente
            throw new EnvioPendienteException(mov.numeroRegistro());   // el registro se reintenta
        }
        return;                // otros códigos: no se registra en control; el fuente tampoco
    }
    estado.contaEnviado();
    control.save(new ControlEnvio(m.numero(), mov.autorizacion(), Estatus.ENVIADO,   // 1
                                  mov.numeroRegistro(), ocurrencia));
}

@Component
@RequiredArgsConstructor
class RespuestaTandemHandler {
    private final ControlEnvioRepository control;
    private final EstadoEnvio estado;

    /** ENVIA_L009(RSTL, NUM_SEC): la invoca el lado receptor con el resultado de cada mensaje. */
    @ServiceActivator(inputChannel = "respuestasTandem")
    @Transactional
    public void onRespuesta(RespuestaTandem r) {
        bitacora.registra(r);                                     // WRITE(SALIDA,...)
        control.findById(r.numeroMensaje()).ifPresent(c -> {
            switch (r.resultado()) {
                case 1 -> { c.estatus(Estatus.CONFIRMADO); estado.contaIbm(); }        // 3
                case 2 -> { c.estatus(Estatus.RECHAZADO);  estado.marcaRechazos();      // 2: activa reenvío
                            estado.contaError(); }
                case 3 -> { c.estatus(Estatus.CONFIRMADO); estado.contaDuplicado(); }   // 3
                default -> estado.contaRespuestaNoConsiderada();   // el estatus no cambia
            }
        });
    }
}

/** EJECUTA_HI: los HI del operador pasan a un endpoint de administración protegido. */
@Component
@Endpoint(id = "l009")
@RequiredArgsConstructor
class ComandosOperador {
    private final EstadoEnvio estado;
    private final EnvioMovimientos envio;

    @WriteOperation
    public String ejecuta(@Selector int hi) {
        switch (hi) {
            case 11  -> { estado.desligaTcpManual(); notificador.carrierDesligado(); }
            case 12  -> { if (estado.hi11()) { estado.ligaTcpManual(); notificador.carrierLigado(); } }
            case 14  -> estado.ajustaBloque(+50, 100, 400);       // NUM_REGISTROS entre 100 y 400
            case 15  -> estado.ajustaBloque(-50, 100, 400);
            case 151 -> envio.reprocesaDesdeInicio();             // NUMERO_ARCHIVO := 0, NREG_MOVS := 1
            case 152 -> envio.reenviaConEstatus(Estatus.ENVIADO); // estatus 1
            case 153 -> envio.reenviaConEstatus(Estatus.RECHAZADO); // estatus 2
            default  -> { return ayuda(); }
        }
        return "OK";
    }
}
